import { injectable } from 'inversify'
import { TransformationDynamicTypeAbstract } from '../transformation-dynamic-type-abstract'
import { MirrorTransformationComponent } from './mirror-transformation-component'
import { type TransformationComponent } from '../../types/transformation-component-types'

export interface MirrorTransformationConfig {
  mode?: 'horizontal' | 'vertical'
}

@injectable()
export class MirrorTransformationType extends TransformationDynamicTypeAbstract<MirrorTransformationConfig> {
  readonly id = 'mirror'

  getLabel (): string {
    return 'Mirror'
  }

  getSummary (config: MirrorTransformationConfig): string {
    return `Mirror ${config.mode ?? 'horizontal'}`
  }

  getReactComponent (): TransformationComponent {
    return MirrorTransformationComponent
  }
}
